select c.segment, count(*) as applications_submitted, countif(a.final_outcome='APPROVE') as applications_approved
from `fennmoor-dw.dw_risk.fct_credit_applications` a left join `fennmoor-dw.dw_core.dim_customer` c using (customer_key)
where a.submitted_date >= '2026-04-07' group by 1 order by 1
